// Deployed web worker entry (packages/infra/alchemy.run.ts `entrypoint`): API
// paths go to the API worker over the service binding (src/lib/api-proxy.ts),
// everything else to the OpenNext handler built into .open-next/.
// biome-ignore lint/suspicious/noTsIgnore: the file may or may not exist when tsc runs, so @ts-expect-error would fail one of the two cases.
// @ts-ignore — generated by `opennextjs-cloudflare build`, absent until then.
import { default as nextHandler } from "./.open-next/worker.js";
import { proxyApiRequest } from "./src/lib/api-proxy";

export default {
	fetch(request: Request, env: { API?: Fetcher }, ctx: ExecutionContext) {
		return proxyApiRequest(request, env) ?? nextHandler.fetch(request, env, ctx);
	},
};
